import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Privacy Policy","description":"Clash collects no app or VPN data. Learn how profiles, credentials, logs, diagnostics, iCloud backups, and user-directed network requests are handled.","frontmatter":{"title":"Privacy Policy","description":"Clash collects no app or VPN data. Learn how profiles, credentials, logs, diagnostics, iCloud backups, and user-directed network requests are handled.","keywords":["Clash Privacy Policy","Clash VPN data","iOS proxy data collection","VPN privacy policy","local profile privacy"],"jsonLd":{"@context":"https://schema.org","@type":"WebPage","name":"Clash Privacy Policy","description":"Clash collects no app or VPN data and explains local profiles, diagnostics, and user-directed requests.","url":"https://clash.md/privacy","inLanguage":"en-US","about":["VPN data","local profiles","diagnostics","iCloud backup"],"publisher":{"@type":"Organization","name":"OmniWide Media Limited","email":"legal@omniwide.media"}}},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1785318168000}`),a={name:`privacy.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p><strong>Last updated: 29 July 2026</strong></p><p>Clash is a network utility that runs on your device. It is not a proxy service: it connects to the services <strong>you</strong> configure, and it has no developer-operated server behind it.</p><p>Clash is published by, and “we” in this policy means, <strong>OmniWide Media Limited</strong>.</p><h2 id="what-we-collect" tabindex="-1">What we collect <a class="header-anchor" href="#what-we-collect" aria-label="Permalink to “What we collect”">​</a></h2><p>Nothing.</p><p>Clash has no account system, analytics, telemetry, advertising SDK, tracking SDK, third-party crash reporter, or automatic diagnostics uploader. Its privacy manifest declares no collected data types, no tracking, and no tracking domains.</p><p>Under Apple&#39;s App Privacy definition, information processed only on the device is not collected. We do not transmit app or VPN data to ourselves or to analytics, advertising, or data-broker partners.</p><h2 id="vpn-data-commitment" tabindex="-1">VPN data commitment <a class="header-anchor" href="#vpn-data-commitment" aria-label="Permalink to “VPN data commitment”">​</a></h2><p>We do not collect or sell user data, use it for our own purposes, or disclose it to third parties. Clash processes network traffic on the device only as necessary to provide the functionality you request.</p><p>The proxy, DNS, subscription, provider, and test services you configure are user-directed external services, not services operated by us and not data recipients selected by us.</p><h2 id="what-stays-on-your-device" tabindex="-1">What stays on your device <a class="header-anchor" href="#what-stays-on-your-device" aria-label="Permalink to “What stays on your device”">​</a></h2><ul><li><strong>Profiles and configurations</strong> are stored byte for byte as you supplied them, including credentials contained in those files. They are protected by iOS data protection and the app container.</li><li><strong>App settings</strong> are stored locally in the app container. Sensitive local proxy-sharing credentials are stored in the device Keychain.</li><li><strong>Connection and request activity</strong> is bounded operational information shown in the app. Live and recent connection data is capped, held locally, and is not uploaded by Clash. Clash does not record the contents of your traffic.</li><li><strong>Logs and diagnostics</strong> remain local. Clash can receive privacy-filtered Apple MetricKit diagnostics on the device, but it has no automatic uploader. Data leaves the device only when you explicitly use an export or share action, in which case you choose the destination.</li></ul><h2 id="user-directed-network-connections" tabindex="-1">User-directed network connections <a class="header-anchor" href="#user-directed-network-connections" aria-label="Permalink to “User-directed network connections”">​</a></h2><p>Clash makes network connections to provide features you configure or start:</p><ul><li><strong>Subscription, rule-provider, proxy-provider, proxy, and DNS services</strong> named by your configuration. Depending on the service, it may receive your IP address, request time, authentication information, DNS queries, traffic metadata, and the content that the selected protocol can access.</li><li><strong>Resource updates</strong> from the URLs shown on the Resources page. Default geo database sources point to the MetaCubeX <code>meta-rules-dat</code> releases on GitHub.</li><li><strong>Diagnostics you start.</strong> The network-quality test contacts Apple&#39;s measurement endpoint. STUN contacts the server you enter. Latency tests contact the URL configured for the selected group.</li><li><strong>Configured background updates.</strong> When enabled, Clash may check configured subscriptions and resources in the background for the purpose you selected.</li></ul><p>These external services operate under their own terms and privacy policies. We do not control them and do not receive the data they process.</p><p>Clash does not contact any service in the background for our benefit. Automatic subscription and resource updates run only when you configure or enable them.</p><h2 id="icloud-backup" tabindex="-1">iCloud backup <a class="header-anchor" href="#icloud-backup" aria-label="Permalink to “iCloud backup”">​</a></h2><p>If you explicitly create an iCloud backup, the backup is stored in <strong>your</strong> iCloud account under Apple&#39;s terms. We do not have access to it.</p><h2 id="retention-deletion-and-privacy-choices" tabindex="-1">Retention, deletion, and privacy choices <a class="header-anchor" href="#retention-deletion-and-privacy-choices" aria-label="Permalink to “Retention, deletion, and privacy choices”">​</a></h2><p>Because we collect no data and provide no account, there is no server-side user profile or developer-held personal data to retain or delete.</p><ul><li>Local profiles, settings, credentials, logs, and diagnostics remain on the device until you delete the relevant item, use <strong>Clear All Local Data</strong>, or uninstall Clash.</li><li><strong>Clear All Local Data</strong> removes local profiles, settings, and Keychain credentials. It does not delete iCloud backups.</li><li>Current iCloud backups can be deleted from Clash&#39;s <strong>Backup &amp; Restore</strong> page by swiping the backup and choosing <strong>Delete</strong>.</li><li>You can stop user-directed processing by disconnecting, removing a profile, disabling configured updates, or choosing not to run or export diagnostics.</li></ul><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to “Children”">​</a></h2><p>Clash is a general network utility and is not directed at children. We do not knowingly collect personal data from anyone, including children.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to “Changes to this policy”">​</a></h2><p>We may update this policy when the app or its data practices change. The current version and update date will be published at this URL. Material changes will also be reflected in the app or its release information.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>If you wish to contact us regarding this Privacy Policy or any privacy-related matters, please contact us via email at <a href="mailto:legal@omniwide.media" target="_blank" rel="noreferrer">legal@omniwide.media</a>, or via postal mail at <strong>OmniWide Media Limited, 128 City Road, London, United Kingdom, EC1V 2NX</strong>.</p><p>For non-confidential questions, you may use the <a href="https://github.com/TokenPLS/Hako-Client/issues" target="_blank" rel="noreferrer">Clash client issue tracker</a>. Never post subscription URLs, credentials, server addresses, private logs, or other sensitive information in a public issue.</p>`,30)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};